declare @languageseq  int 

create table #pgmseq(
pgmseq int )

/*
신규 스크립트 
업데이트는 많지 않아서 개별적으로 작업
minorvalue 값은 마스터 하나 걸려 있어서 체크후 패치 


*/

--==============================
--1.미번역건 집계  
--===============================
insert into #pgmseq
select 0


select @languageseq =2 


--================================
--코드정보 담기                                  
--================================					
;WITH CTE_Seq AS (
select CASE WHEN CodehelpConst = 19998 THEN 1   --시스템 
            WHEN CodehelpConst = 19999 THEN 2   --사용자
            ELSE 3                              --코드도움
            END AS TYPE,
            CodehelpConst,substring(CodeHelpParams,0,dbo.fn_find('|',CodeHelpParams,1)) as CodeHelpParams
  from _TCApgm as a 
    left join IAMCCOMMON.._tcapgmcontrols as b on b.pgmseq=a.pgmseq
    join #PGMSEQ as c on c.pgmseq =a.pgmseq 
 where CodehelpConst<>0

union 
 select CASE WHEN CodehelpConst = 19998 THEN 1   --시스템 
            WHEN CodehelpConst = 19999 THEN 2   --사용자
            ELSE 3                              --코드도움
            END,
            CodeHelpConst,substring(CodeHelpParams,0,dbo.fn_find('|',CodeHelpParams,1))
  from _TCApgm as a 
    left join IAMCCOMMON.._tcapgmSheets as b on b.pgmseq=a.pgmseq
    join #PGMSEQ as c on c.pgmseq =a.pgmseq 
 where  CodehelpConst<>0
)



SELECT * INTO #Temp_Seq FROM CTE_Seq

delete from #Temp_Seq

--=======추가 코드 도움 변수======

insert into #Temp_Seq(type,CodeHelpConst,CodeHelpParams)
select 2,19999,1100202
union all
select 2,19999,1100206



select @languageseq
select * from #Temp_Seq



select 'IF NOT EXISTS(SELECT 1 FROM _tdasmajor WHERE '+'MajorSeq	='+CONVERT(VARCHAR(30), ISNULL(MajorSeq, 0))+' )'+CHAR(13)+'BEGIN '+CHAR(13)+ 'INSERT _TDASMajor(CompanySeq, MajorSeq, MajorName, Remark, SysType, FixCombo, IsCombo, WordSeq, LastUserSeq, LastDateTime, CustSeq, DevMode) '+CHAR(13)+ + 'SELECT '+ CASE WHEN 'CompanySeq' IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, 'CompanySeq') END + ',' + CASE WHEN A.MajorSeq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.MajorSeq) END + ',' + CASE WHEN A.MajorName IS NULL THEN N'NULL' ELSE 'N''' + (A.MajorName) + '''' END + ',' + CASE WHEN A.Remark IS NULL THEN N'NULL' ELSE 'N''' + (A.Remark) + '''' END + ',' + CASE WHEN A.SysType IS NULL THEN N'NULL' ELSE 'N''' + (A.SysType) + '''' END + ',' + CASE WHEN A.FixCombo IS NULL THEN N'NULL' ELSE 'N''' + (A.FixCombo) + '''' END + ',' + CASE WHEN A.IsCombo IS NULL THEN N'NULL' ELSE 'N''' + (A.IsCombo) + '''' END + ',' + CASE WHEN A.WordSeq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.WordSeq) END + ',' + CASE WHEN A.LastUserSeq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.LastUserSeq) END + ',' + CASE WHEN A.LastDateTime IS NULL THEN N'NULL' ELSE '''' + CONVERT(NVARCHAR, A.LastDateTime, 121) + '''' END + ',' + CASE WHEN A.CustSeq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.CustSeq) END + ',' + CASE WHEN A.DevMode IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.DevMode) END +' FROM _TCACOMPANY'+CHAR(13)+' end' FROM _TDASMajor AS A WITH(NOLOCK) 
 join #Temp_Seq as b on type =1 and CodeHelpParams = a.majorseq
  union all 
 select 'IF NOT EXISTS(SELECT 1 FROM _tdasminor WHERE '+'MinorSeq	='+CONVERT(VARCHAR(30), ISNULL(MinorSeq, 0))+' )'+CHAR(13)+'BEGIN '+CHAR(13)+ 'INSERT _TDASMinor(CompanySeq, MinorSeq, MajorSeq, MinorName, MinorValue, MinorSort, Remark, WordSeq, LastUserSeq, LastDateTime, IsUse) '+CHAR(13)+ + 'SELECT '+ CASE WHEN 'CompanySeq' IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, 'CompanySeq') END + ',' + CASE WHEN A.MinorSeq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.MinorSeq) END + ',' + CASE WHEN A.MajorSeq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.MajorSeq) END + ',' + CASE WHEN A.MinorName IS NULL THEN N'NULL' ELSE 'N''' + (A.MinorName) + '''' END + ',' + CASE WHEN A.MinorValue IS NULL THEN N'NULL' ELSE 'N''' + (A.MinorValue) + '''' END + ',' + CASE WHEN A.MinorSort IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.MinorSort) END + ',' + CASE WHEN A.Remark IS NULL THEN N'NULL' ELSE 'N''' + (A.Remark) + '''' END + ',' + CASE WHEN A.WordSeq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.WordSeq) END + ',' + CASE WHEN A.LastUserSeq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.LastUserSeq) END + ',' + CASE WHEN A.LastDateTime IS NULL THEN N'NULL' ELSE '''' + CONVERT(NVARCHAR, A.LastDateTime, 121) + '''' END + ',' + CASE WHEN A.IsUse IS NULL THEN N'NULL' ELSE 'N''' + (A.IsUse) + '''' END +' FROM _TCACOMPANY'+CHAR(13)+' end' FROM _TDASMinor AS A WITH(NOLOCK) 
  join #Temp_Seq as b on type =1 and CodeHelpParams = a.majorseq
   union all 
 select 'IF NOT EXISTS(SELECT 1 FROM _tcomuserdefine WHERE '+'TableName	='+''''+CONVERT(VARCHAR(30), ISNULL(TableName, 0))+''''+' AND '+'TitleSerl	='+CONVERT(VARCHAR(30), ISNULL(TitleSerl, 0))+' AND '+'DefineUnitSeq	='+CONVERT(VARCHAR(30), ISNULL(DefineUnitSeq, 0))+' )'+CHAR(13)+'BEGIN '+CHAR(13)+ 'INSERT _TCOMUserDefine(CompanySeq, TableName, DefineUnitSeq, TitleSerl, Title, IsEss, CodeHelpConst, CodeHelpParams, SMInputType, MaskAndCaption, QrySort, IsFix, DataFieldID, IsCodeHelpTitle, LastUserSeq, LastDateTime, DecLen, WordSeq) '+CHAR(13)+ + 'SELECT '+ CASE WHEN 'CompanySeq' IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, 'CompanySeq') END + ',' + CASE WHEN A.TableName IS NULL THEN N'NULL' ELSE 'N''' + (A.TableName) + '''' END + ',' + CASE WHEN A.DefineUnitSeq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.DefineUnitSeq) END + ',' + CASE WHEN A.TitleSerl IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.TitleSerl) END + ',' + CASE WHEN A.Title IS NULL THEN N'NULL' ELSE 'N''' + (A.Title) + '''' END + ',' + CASE WHEN A.IsEss IS NULL THEN N'NULL' ELSE 'N''' + (A.IsEss) + '''' END + ',' + CASE WHEN A.CodeHelpConst IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.CodeHelpConst) END + ',' + CASE WHEN A.CodeHelpParams IS NULL THEN N'NULL' ELSE 'N''' + (A.CodeHelpParams) + '''' END + ',' + CASE WHEN A.SMInputType IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.SMInputType) END + ',' + CASE WHEN A.MaskAndCaption IS NULL THEN N'NULL' ELSE 'N''' + (A.MaskAndCaption) + '''' END + ',' + CASE WHEN A.QrySort IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.QrySort) END + ',' + CASE WHEN A.IsFix IS NULL THEN N'NULL' ELSE 'N''' + (A.IsFix) + '''' END + ',' + CASE WHEN A.DataFieldID IS NULL THEN N'NULL' ELSE 'N''' + (A.DataFieldID) + '''' END + ',' + CASE WHEN A.IsCodeHelpTitle IS NULL THEN N'NULL' ELSE 'N''' + (A.IsCodeHelpTitle) + '''' END + ',' + CASE WHEN A.LastUserSeq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.LastUserSeq) END + ',' + CASE WHEN A.LastDateTime IS NULL THEN 