A.IsCombo) + '''' END + ',' + CASE WHEN A.PageCount IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.PageCount) END + ',' + CASE WHEN A.Param1 IS NULL THEN N'NULL' ELSE 'N''' + (A.Param1) + '''' END + ',' + CASE WHEN A.Param2 IS NULL THEN N'NULL' ELSE 'N''' + (A.Param2) + '''' END + ',' + CASE WHEN A.Param3 IS NULL THEN N'NULL' ELSE 'N''' + (A.Param3) + '''' END + ',' + CASE WHEN A.Param4 IS NULL THEN N'NULL' ELSE 'N''' + (A.Param4) + '''' END + ',' + CASE WHEN A.LastUserSeq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.LastUserSeq) END + ',' + CASE WHEN A.LastDateTime IS NULL THEN N'NULL' ELSE '''' + CONVERT(NVARCHAR, A.LastDateTime, 121) + '''' END + ',' + CASE WHEN A.FixCombo IS NULL THEN N'NULL' ELSE 'N''' + (A.FixCombo) + '''' END + ',' + CASE WHEN A.TableName IS NULL THEN N'NULL' ELSE 'N''' + (A.TableName) + '''' END + ',' + CASE WHEN A.SeqColumnName IS NULL THEN N'NULL' ELSE 'N''' + (A.SeqColumnName) + '''' END + ',' + CASE WHEN A.NameColumnName IS NULL THEN N'NULL' ELSE 'N''' + (A.NameColumnName) + '''' END + ',' + CASE WHEN A.RefColumnName IS NULL THEN N'NULL' ELSE 'N''' + (A.RefColumnName) + '''' END + ',' + CASE WHEN A.DBType IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.DBType) END + ',' + CASE WHEN A.QuickHelpSpName IS NULL THEN N'NULL' ELSE 'N''' + (A.QuickHelpSpName) + '''' END + ',' + CASE WHEN A.QuickHelpSeq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.QuickHelpSeq) END + ',' + CASE WHEN A.SecuClass IS NULL THEN N'NULL' ELSE 'N''' + (A.SecuClass) + '''' END + ',' + CASE WHEN A.CodeHelpAssistSPName IS NULL THEN N'NULL' ELSE 'N''' + (A.CodeHelpAssistSPName) + '''' END + ',' + CASE WHEN A.IsMulti IS NULL THEN N'NULL' ELSE 'N''' + (A.IsMulti) + '''' END + ',' + CASE WHEN A.IsMultiAssist IS NULL THEN N'NULL' ELSE 'N''' + (A.IsMultiAssist) + '''' END + ',' + CASE WHEN A.PagingType IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.PagingType) END + ',' + CASE WHEN A.CustSeq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.CustSeq) END + ',' + 