 join #Temp_Seq as b on type =3 and CodeHelpConst = a.CodeHelpSeq
  union all 
 select 'IF NOT EXISTS(SELECT 1 FROM _tcacodehelptitle WHERE '+'CodeHelpSeq	='+CONVERT(VARCHAR(30), ISNULL(CodeHelpSeq, 0))+' AND '+'TitleSeq	='+CONVERT(VARCHAR(30), ISNULL(TitleSeq, 0))+' )'+CHAR(13)+'BEGIN '+CHAR(13)+ 'INSERT _TCACodeHelpTitle(CompanySeq, CodeHelpSeq, TitleSeq, TitleName, FieldName, TitleWidth, IsVisible, DataType, MaskFormat, DecMaxLength, FieldType, LastUserSeq, LastDateTime, WordSeq) '+CHAR(13)+ + 'SELECT '+ CASE WHEN 'CompanySeq' IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, 'CompanySeq') END + ',' + CASE WHEN A.CodeHelpSeq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.CodeHelpSeq) END + ',' + CASE WHEN A.TitleSeq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.TitleSeq) END + ',' + CASE WHEN A.TitleName IS NULL THEN N'NULL' ELSE 'N''' + (A.TitleName) + '''' END + ',' + CASE WHEN A.FieldName IS NULL THEN N'NULL' ELSE 'N''' + (A.FieldName) + '''' END + ',' + CASE WHEN A.TitleWidth IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.TitleWidth) END + ',' + CASE WHEN A.IsVisible IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.IsVisible) END + ',' + CASE WHEN A.DataType IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.DataType) END + ',' + CASE WHEN A.MaskFormat IS NULL THEN N'NULL' ELSE 'N''' + (A.MaskFormat) + '''' END + ',' + CASE WHEN A.DecMaxLength IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.DecMaxLength) END + ',' + CASE WHEN A.FieldType IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.FieldType) END + ',' + CASE WHEN A.LastUserSeq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.LastUserSeq) END + ',' + CASE WHEN A.LastDateTime IS NULL THEN N'NULL' ELSE '''' + CONVERT(NVARCHAR, A.LastDateTime, 121) + '''' END + ',' + CASE WHEN A.WordSeq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.WordSeq) END +' FROM _TCACOMPANY'+CHAR(13)+' end' FROM _TCACodeHelpTitle AS A WITH(NOLOCK) 
 join #Temp_Seq as b on type =3 and CodeHelpConst = a.CodeHelpSeq
  union all 
 select 'IF NOT EXISTS(SELECT 1 FROM _tcacodehelpoption WHERE '+'CodeHelpSeq	='+CONVERT(VARCHAR(30), ISNULL(CodeHelpSeq, 0))+' AND '+'OptionSeq	='+CONVERT(VARCHAR(30), ISNULL(OptionSeq, 0))+' )'+CHAR(13)+'BEGIN '+CHAR(13)+ 'INSERT _TCACodeHelpOption(Seq, CompanySeq, CodeHelpSeq, OptionSeq, OptionName, FieldName, IsVisible, LastUserSeq, LastDateTime, WordSeq) '+CHAR(13)+ + 'SELECT '+ CASE WHEN A.Seq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.Seq) END + ',' + CASE WHEN 'CompanySeq' IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, 'CompanySeq') END + ',' + CASE WHEN A.CodeHelpSeq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.CodeHelpSeq) END + ',' + CASE WHEN A.OptionSeq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.OptionSeq) END + ',' + CASE WHEN A.OptionName IS NULL THEN N'NULL' ELSE 'N''' + (A.OptionName) + '''' END + ',' + CASE WHEN A.FieldName IS NULL THEN N'NULL' ELSE 'N''' + (A.FieldName) + '''' END + ',' + CASE WHEN A.IsVisible IS NULL THEN N'NULL' ELSE 'N''' + (A.IsVisible) + '''' END + ',' + CASE WHEN A.LastUserSeq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.LastUserSeq) END + ',' + CASE WHEN A.LastDateTime IS NULL THEN N'NULL' ELSE '''' + CONVERT(NVARCHAR, A.LastDateTime, 121) + '''' END + ',' + CASE WHEN A.WordSeq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.WordSeq) END +' FROM _TCACOMPANY'+CHAR(13)+' end' FROM _TCACodeHelpOption AS A WITH(NOLOCK) 
 join #Temp_Seq as b on type =3 and CodeHelpConst = a.CodeHelpSeq
 union all 
 select 'IF NOT EXISTS(SELECT 1 FROM _tcacodehelpsubcondition WHERE '+'CodeHelpSeq	='+CONVERT(VARCHAR(30), ISNULL(CodeHelpSeq, 0))+' AND '+'SubConditionSeq	='+CONVERT(VARCHAR(30), ISNULL(SubConditionSeq, 0))+' )'+CHAR(13)+'BEGIN '+CHAR(13)+ 'INSERT _TCACodeHelpSubCondition(CompanySeq, CodeHelpSeq, SubConditionSeq, SubConditionName, SqlScript, Remark, SortOrder, LastUserSeq, LastDateTime, IsDefault, WordSeq) '+CHAR(13)+ + 'SELECT '+ CASE WHEN 'CompanySeq' IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, 'CompanySeq') END + ',' + CASE WHEN A.CodeHelpSeq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.CodeHelpSeq) END + ',' + CASE WHEN A.SubConditionSeq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.SubConditionSeq) END + ',' + CASE WHEN A.SubConditionName IS NULL THEN N'NULL' ELSE 'N''' + (A.SubConditionName) + '''' END + ',' + CASE WHEN A.SqlScript IS NULL THEN N'NULL' ELSE 'N''' + (A.SqlScript) + '''' END + ',' + CASE WHEN A.Remark IS NULL THEN N'NULL' ELSE 'N''' + (A.Remark) + '''' END + ',' + CASE WHEN A.SortOrder IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.SortOrder) END + ',' + CASE WHEN A.LastUserSeq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.LastUserSeq) END + ',' + CASE WHEN A.LastDateTime IS NULL THEN N'NULL' ELSE '''' + CONVERT(NVARCHAR, A.LastDateTime, 121) + '''' END + ',' + CASE WHEN A.IsDefault IS NULL THEN N'NULL' ELSE 'N''' + (A.IsDefault) + '''' END + ',' + CASE WHEN A.WordSeq IS NULL THEN N'NULL' ELSE CONVERT(NVARCHAR, A.WordSeq) END +' FROM _TCACOMPANY'+CHAR(13)+' end' FROM _TCACodeHelpSubCondition AS A WITH(NOLOCK) 
 join #Temp_Seq as b on type =3 and CodeHelpConst = a.CodeHelpSeq


 
drop table #Temp_Seq
drop table #pgmseq